"""Carry immutable generated bytes through later manual edits for refresh review."""


def prepare_baselines(db, entries, base, generated_paths):
    if not isinstance(generated_paths, tuple) or len(set(generated_paths)) != len(generated_paths):
        raise ValueError("Generated page paths must be explicit and distinct")
    files = {path: (digest, size) for path, digest, size in entries}
    previous = (
        {
            path: (digest, size)
            for path, digest, size in read_baselines(db.connection, base.publication.revision_id)
            if path in files
        }
        if base is not None
        else {}
    )
    for path in generated_paths:
        if path not in files or not path.endswith(".md"):
            raise ValueError("Generated baselines must identify retained Markdown pages")
        previous[path] = files[path]
    return [(path, *previous[path]) for path in sorted(previous)]


def read_baselines(connection, revision_id):
    return connection.execute(
        "SELECT path, digest, byte_count FROM ukb_revision_generated "
        "WHERE revision_id = ? ORDER BY path",
        (revision_id,),
    ).fetchall()


def require_refresh_catalog(connection, revision_id):
    from .catalog_store import CatalogConflict

    expected = read_refresh_generation(connection, revision_id)
    if expected is not None and connection.execute(
        "SELECT generation FROM ukb_catalog_state WHERE singleton = 1"
    ).fetchone() != (expected,):
        raise CatalogConflict("Sources or processing targets changed after refresh preparation")


def read_refresh_generation(connection, revision_id):
    row = connection.execute(
        "SELECT catalog_generation FROM ukb_revision_refresh WHERE revision_id = ?", (revision_id,)
    ).fetchone()
    return row[0] if row else None
